-- Exportacion interna de TI: evidencia visual del aviso de privacidad.
-- Genera un HTML listo para abrir e imprimir como PDF.

\encoding UTF8
\copy (SELECT '<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Sigil.IA - Registro de consentimiento</title><style>body{font-family:Arial,sans-serif;color:#131b2e;margin:40px;background:#f4f7ff}header{background:#1d4ed8;color:#fff;padding:24px 30px;border-radius:12px 12px 0 0}h1{margin:0;font-size:25px}h2{margin:5px 0 0;font-size:14px;font-weight:400}main{background:#fff;padding:28px 30px;border-radius:0 0 12px 12px;box-shadow:0 8px 25px #13204a22}.meta{display:flex;gap:30px;margin-bottom:22px;color:#606477;font-size:12px}.section{color:#0037b0;font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}table{width:100%;border-collapse:collapse;margin-top:12px;font-size:11px}th{padding:11px;text-align:left;color:#fff;background:#0037b0}td{padding:10px;border-bottom:1px solid #dfe4f2;vertical-align:top}tr:nth-child(even){background:#f7f9ff}.ok{color:#147a3d;font-weight:700}.details{white-space:normal;max-width:300px;font-family:Consolas,monospace;font-size:10px;line-height:1.35}footer{margin-top:22px;color:#606477;font-size:10px}</style></head><body><header><h1>Sigil.IA</h1><h2>Lectura del aviso y registro de consentimiento</h2></header><main><div class="meta"><span><b>Documento:</b> Aviso de privacidad</span><span><b>Versi&oacute;n:</b> 1.0</span><span><b>Generado:</b> ' || to_char(CURRENT_TIMESTAMP AT TIME ZONE 'America/Mexico_City','YYYY-MM-DD HH24:MI:SS') || ' (hora de M&eacute;xico)</span></div><div class="section">Evidencia registrada en PostgreSQL</div><table><thead><tr><th>Registro</th><th>Secci&oacute;n</th><th>Acci&oacute;n</th><th>Aceptado</th><th>Fecha y hora</th><th>IP / navegador</th><th>Detalles</th></tr></thead><tbody>' || COALESCE(string_agg(format('<tr><td>%s</td><td>Lectura del aviso y registro de consentimiento</td><td>%s</td><td class="ok">%s</td><td>%s</td><td>%s<br>%s</td><td class="details">%s</td></tr>', id, action, CASE WHEN COALESCE(details->>'accepted','false') = 'true' THEN 'S&iacute;' ELSE 'No' END, to_char(created_at AT TIME ZONE 'America/Mexico_City','YYYY-MM-DD HH24:MI:SS'), COALESCE(host(ip_address),'N/D'), COALESCE(replace(replace(replace(user_agent,'&','&amp;'),'<','&lt;'),'>','&gt;'),'N/D'), replace(replace(replace(replace(jsonb_pretty(details),'&','&amp;'),'<','&lt;'),'>','&gt;'),chr(10),'<br>')), chr(10) ORDER BY created_at DESC), '<tr><td colspan="7">No hay registros de aceptaci&oacute;n del aviso.</td></tr>') || '</tbody></table><footer>Documento generado exclusivamente para auditor&iacute;a interna. La consulta es de solo lectura y no modifica la tabla audit_logs.</footer></main></body></html>' FROM audit_logs WHERE action = 'PRIVACY_NOTICE_ACCEPTED') TO 'sigilia-privacy-consent-audit.html' WITH (FORMAT text, ENCODING 'UTF8');
